insert into public.colaboradores_cadastrados (nome, cpf, setor)
select distinct on (cpf)
  nome,
  cpf,
  setor
from (
  select
    btrim(nome) as nome,
    regexp_replace(cpf, '[^0-9]', '', 'g') as cpf,
    btrim(setor) as setor
  from colaboradores_import
) as colaboradores_normalizados
where nome <> ''
  and cpf ~ '^[0-9]{11}$'
  and setor <> ''
order by cpf, nome
on conflict (cpf) do update
set nome = excluded.nome,
    setor = excluded.setor;

alter table public.colaboradores_cadastrados enable row level security;

revoke all on table public.colaboradores_cadastrados from anon;
grant select on table public.colaboradores_cadastrados to authenticated;

drop policy if exists colaboradores_cadastrados_admin_select
on public.colaboradores_cadastrados;

create policy colaboradores_cadastrados_admin_select
on public.colaboradores_cadastrados
for select
to authenticated
using (
  exists (
    select 1
    from public.profiles p
    where p.id = (select auth.uid())
      and p.approved = true
      and p.role = 'admin'
  )
);

comment on table public.colaboradores_cadastrados is
  'Cadastro administrativo de colaboradores importado apenas com nome, CPF e setor.';
